#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
int main(int ac,char**av){FILE*f,*o;long len;unsigned char*d,*p;size_t st,sz;unsigned long nt=0;int cols,rows,w,h,i,x,y,v; if(ac<3){fprintf(stderr,"usage: nes-chr-c IMAGE OUTPUT.ppm [--tiles N]\n");return 2;}if(ac==5&&!strcmp(av[3],"--tiles"))nt=strtoul(av[4],0,10);else if(ac!=3)return 2;f=fopen(av[1],"rb");if(!f){perror(av[1]);return 2;}fseek(f,0,SEEK_END);len=ftell(f);rewind(f);if(len<16)return 2;d=(unsigned char*)malloc((size_t)len);if(!d||fread(d,1,(size_t)len,f)!=(size_t)len)return 2;fclose(f);if(memcmp(d,"NES\032",4)||(d[7]&12)!=0&&(d[7]&12)!=8||!d[5]){fprintf(stderr,"error: unsupported header or no CHR ROM\n");return 2;}if((d[7]&12)==8&&((d[9]&15)==15||(d[9]>>4)==15))return 2;st=16+((d[6]&4)?512:0)+(size_t)d[4]*16384;sz=(size_t)d[5]*8192;if(st+sz>(size_t)len)return 2;if(!nt)nt=sz/16;if(!nt||nt>sz/16)return 2;cols=nt<16?(int)nt:16;rows=(int)((nt+cols-1)/cols);w=cols*8;h=rows*8;p=(unsigned char*)calloc((size_t)w*h,3);if(!p)return 2;for(i=0;i<(int)nt;i++)for(y=0;y<8;y++)for(x=0;x<8;x++){unsigned char*t=d+st+(size_t)i*16;v=((t[y]>>(7-x))&1)|(((t[y+8]>>(7-x))&1)<<1);p[((size_t)(i/cols*8+y)*w+i%cols*8+x)*3]=(unsigned char)(v*85);p[((size_t)(i/cols*8+y)*w+i%cols*8+x)*3+1]=(unsigned char)(v*85);p[((size_t)(i/cols*8+y)*w+i%cols*8+x)*3+2]=(unsigned char)(v*85);}o=fopen(av[2],"wb");if(!o)return 2;fprintf(o,"P6\n%d %d\n255\n",w,h);fwrite(p,1,(size_t)w*h*3,o);fclose(o);free(p);free(d);printf("wrote %dx%d PPM atlas\n",w,h);return 0;}
